def _get_musl_version(executable: str) -> Optional[MuslVersion]:
    """Detect the musl version from the executable.

    This is done by running the executable's interpreter and parsing the output.
    See https://github.com/pypa/packaging/pull/563 for details.

    :param executable: Path to the executable.
    """
    try:
        with open(executable, "rb") as f:
            ld = ELFFile(f).interpreter
    except (OSError, TypeError, ValueError):
        return None
    if ld is None or "musl" not in ld:
        return None
    proc = subprocess.run([ld], stderr=subprocess.PIPE, text=True)
    return _parse_musl_version(proc.stderr)

